var DISTRICT_LABELS = { oldtown: [-380, -60], ensanche: [-700, 600], downtown: [50, -2050], campus: [-900, -1700], beach: [-1550, 300], port: [-1400, 1700], poligono: [150, 1800], barrio: [-200, 1200], hills: [1700, -800], airport: [1700, 1500], island: [-2900, -150], park: [500, 150] };
